sqlMap.insert:
MERGE INTO IF_PODT_DWHA A USING ( SELECT #LEGACY_PO_NO# AS LEGACY_PO_NO, #LEGACY_PO_SEQ# AS LEGACY_PO_SEQ, #STATUS# AS STATUS, #BUYER_ITEM_NO# AS BUYER_ITEM_NO, #ITEM_QTY# AS ITEM_QTY, #IF_NO# || '_' || #IF_SEQ# AS REF_IF_NO FROM DUAL
) B ON ( 1 =1 AND B.LEGACY_PO_NO = A.LEGACY_PO_NO AND B.LEGACY_PO_SEQ = A.LEGACY_PO_SEQ AND B.STATUS = A.STATUS AND B.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND B.ITEM_QTY = A.ITEM_QTY AND B.REF_IF_NO = A.REF_IF_NO ) WHEN MATCHED THEN UPDATE SET KEP_SEQ = SEQ_IF_PODT_DWHA.NEXTVAL , UNIT_PRICE = #UNIT_PRICE# , ADD_DATE = SYSDATE , RD_DATE = #RD_DATE# , PURCHASER_USER_ID = #PURCHASER_ID# , REQ_USER_ID = #REQ_USER_ID# , REQ_USER_DEPT = #EKORG# , IF_FLAG = 'N' , IF_DATE = SYSDATE , IV_COLUMN = #BANFN# || '%%' || #BNFPO# || '%%' || #KNTTP# || '%%' || #ABRAD# || '%%' || #WEMPF# || '%%' || #LGORT# || '%%' || #LGPBE# , PLANT = #PLANT# , REMARK = #REMARK#
WHEN NOT MATCHED THEN INSERT ( KEP_SEQ, LEGACY_PO_NO, LEGACY_PO_SEQ, ITEM_QTY, STATUS, REMARK, REQ_USER_DEPT, PLANT, IV_COLUMN, BUYER_ITEM_NO, UNIT_PRICE, PURCHASER_USER_ID, REQ_USER_ID, ADD_DATE, RD_DATE, REF_IF_NO, IF_FLAG, IF_DATE
) VALUES ( SEQ_IF_PODT_DWHA.NEXTVAL, #LEGACY_PO_NO#, #LEGACY_PO_SEQ#, #ITEM_QTY#, #STATUS#, #REMARK#, #EKORG#, #PLANT#, #BANFN# || '%%' || #BNFPO# || '%%' || #KNTTP# || '%%' || #ABRAD# || '%%' || #WEMPF# || '%%' || #LGORT# || '%%' || #LGPBE#, #BUYER_ITEM_NO#, #UNIT_PRICE#, #PURCHASER_ID#, #REQ_USER_ID#, #ADD_DATE#, SYSDATE, #IF_NO# || '_' || #IF_SEQ#, 'N', SYSDATE
)

MERGE INTO IF_GRDT_DWHA A USING ( SELECT #MJAHR# || #MBLNR# AS LEGACY_GR_NO, #ZEILE# AS LEGACY_GR_SEQ, #LEGACY_PO_NO# AS LEGACY_PO_NO, #LEGACY_PO_SEQ# AS LEGACY_PO_SEQ, #GR_QTY# AS GR_QTY FROM DUAL
) B ON ( 1=1 AND B.LEGACY_GR_NO = A.LEGACY_GR_NO AND B.LEGACY_GR_SEQ = A.LEGACY_GR_SEQ AND B.LEGACY_PO_NO = A.LEGACY_PO_NO AND B.LEGACY_PO_SEQ = A.LEGACY_PO_SEQ AND B.GR_QTY = A.GR_QTY ) WHEN MATCHED THEN UPDATE SET KEP_SEQ = SEQ_IF_GRDT_DWHA.NEXTVAL , GR_DATE = #GR_DATE# , REF_IF_NO = #SJAHR# || #SMBLN# , REF_IF_NO1 = #SMBLP# , IF_FLAG = 'N' WHEN NOT MATCHED THEN INSERT ( KEP_SEQ, LEGACY_GR_NO, LEGACY_GR_SEQ, LEGACY_PO_NO, LEGACY_PO_SEQ, GR_QTY, GR_DATE, REF_IF_NO, REF_IF_NO1, IF_FLAG, IF_DATE
) VALUES ( SEQ_IF_GRDT_DWHA.NEXTVAL, #MJAHR# || #MBLNR#, #ZEILE#, #LEGACY_PO_NO#, #LEGACY_PO_SEQ#, #GR_QTY#, #GR_DATE#, #SJAHR# || #SMBLN#, #SMBLP#, 'N', SYSDATE )
